from pathlib import Path
import json
root=Path(__file__).resolve().parents[1];d=json.loads((root/'data.json').read_text());rows=[]
def row(lec,slides,title,terms='',note='',status='Taught and tested'):
 cs=[]
 for t in terms.split(';'):
  if not t.strip():continue
  hits=[c for c in d['concepts'] if c['term'].lower().startswith(t.strip().lower())]
  assert hits,(lec,t);cs.append(hits[0])
 for n in slides:rows.append(dict(lecture=lec,slide=n,title=title,status=status,note=note,conceptIds=[c['id'] for c in cs],questionIds=[c['firstQuestionId'] for c in cs],essayRoute=f'#essays/{lec}'))
